(function(){'use strict';const $=id=>document.getElementById(id),form=$('f');let current=null,phase='edit';
for(const id of Object.keys(InterestForm.labels)){const box=document.createElement('p');box.id=id+'-error';box.className='field-error';box.hidden=true;$(id).insertAdjacentElement('afterend',box);$(id).setAttribute('aria-describedby',box.id);}
function data(){return Object.fromEntries(Object.keys(InterestForm.labels).map(k=>[k,$(k).value]));}
function clearErrors(){for(const id of Object.keys(InterestForm.labels)){$(id).removeAttribute('aria-invalid');$(id+'-error').textContent='';$(id+'-error').hidden=true;}}
function render(v){$('review-list').replaceChildren();for(const [k,l] of Object.entries(InterestForm.labels)){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=l;dd.textContent=v[k]||'미입력';row.append(dt,dd);$('review-list').append(row);}}
function hideFallback(){$('copy-fallback').hidden=true;$('fallback-label').hidden=true;$('copy-fallback').value='';$('transfer-status').textContent='';}
form.addEventListener('submit',e=>{e.preventDefault();clearErrors();const check=InterestForm.validate(data());if(!check.valid){current=null;for(const [id,m] of Object.entries(check.errors)){$(id).setAttribute('aria-invalid','true');$(id+'-error').textContent=m;$(id+'-error').hidden=false;}$('msg').textContent='표시된 입력 내용을 확인해 주세요.';$(Object.keys(check.errors)[0]).focus();return;}current=check.values;phase='review';render(current);$('msg').textContent='';form.hidden=true;$('review-panel').hidden=false;$('review-actions').hidden=false;$('done-actions').hidden=true;$('stage-label').textContent='2 / 3 · 입력 내용 확인';$('review-heading').textContent='이 내용으로 준비할까요?';hideFallback();$('review-heading').focus();});
function edit(){phase='edit';current=null;$('review-panel').hidden=true;form.hidden=false;hideFallback();$('name').focus();}
$('edit').addEventListener('click',edit);$('edit-again').addEventListener('click',edit);
$('finish').addEventListener('click',()=>{if(phase!=='review'||!current)return;phase='done';$('stage-label').textContent='3 / 3 · 입력 내용 정리 완료';$('review-heading').textContent='참여 의향 내용을 정리했어요';$('review-actions').hidden=true;$('done-actions').hidden=false;$('review-heading').focus();});
$('copy-result').addEventListener('click',async()=>{if(phase!=='done'||!current)return;const text=InterestForm.summary(current);try{await navigator.clipboard.writeText(text);if(phase==='done')$('transfer-status').textContent='개인 보관용 내용을 복사했습니다. 실제 신청 접수는 아닙니다.';}catch(e){if(phase!=='done')return;$('copy-fallback').value=text;$('copy-fallback').hidden=false;$('fallback-label').hidden=false;$('copy-fallback').focus();$('copy-fallback').select();$('transfer-status').textContent='자동 복사가 차단됐습니다. 선택한 내용을 직접 복사해 주세요.';}});
$('download-result').addEventListener('click',()=>{if(phase!=='done'||!current)return;try{const blob=new Blob(['\ufeff'+InterestForm.summary(current)],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Farmcare-interest.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('transfer-status').textContent='텍스트 파일 다운로드를 요청했습니다. 브라우저 다운로드 목록을 확인하세요.';}catch(e){$('transfer-status').textContent='파일을 만들지 못했습니다. 결과 복사를 이용해 주세요.';}});
})();